def _backfill_environment_targets() -> None:
    """Convert existing protected target snapshots without importing service code."""

    connection = op.get_bind()
    revisions = tuple(
        connection.execute(
            sa.text("SELECT id, connection, target_key, created_at FROM environment_revisions")
        ).mappings()
    )
    bindings = tuple(
        connection.execute(
            sa.text(
                "SELECT b.id, b.provider_key, b.target_key, b.created_at, r.status "
                "FROM run_environment_bindings AS b "
                "JOIN runs AS r ON r.tenant_id = b.organization_id AND r.id = b.run_id"
            )
        ).mappings()
    )
    identities: dict[tuple[str, str], dict[str, object]] = {}
    active_counts: dict[tuple[str, str], int] = {}
    revision_targets: dict[str, str] = {}
    binding_targets: dict[str, str] = {}
    now = datetime.now(UTC)

    def require_target(provider_key: str, target_key: str, created_at: datetime) -> str:
        key = (provider_key, target_key)
        payload = {
            "provider_key": provider_key,
            "identity_schema_version": "1",
            "namespace": {},
            "target_key": target_key,
        }
        digest = hashlib.sha256(rfc8785.dumps(payload)).hexdigest()
        target_id = f"envt_{digest}"
        if key not in identities:
            identities[key] = {
                "id": target_id,
                "provider_key": provider_key,
                "identity_schema_version": "1",
                "target_key": target_key,
                "target_identity_digest_sha256": digest,
                # Existing releases contain only built-ins that require no retention.
                "retention_behavior": "none",
                "created_at": created_at,
            }
            active_counts[key] = 0
        return target_id

    for revision_row in revisions:
        raw_connection = revision_row["connection"]
        if isinstance(raw_connection, str):
            raw_connection = json.loads(raw_connection)
        target_id = require_target(
            str(raw_connection["provider_key"]),
            str(revision_row["target_key"]),
            revision_row["created_at"],
        )
        revision_targets[str(revision_row["id"])] = target_id
    for binding_row in bindings:
        target_id = require_target(
            str(binding_row["provider_key"]),
            str(binding_row["target_key"]),
            binding_row["created_at"],
        )
        binding_targets[str(binding_row["id"])] = target_id
        if binding_row["status"] in {"accepted", "running"}:
            key = (str(binding_row["provider_key"]), str(binding_row["target_key"]))
            active_counts[key] += 1

    targets = sa.table(
        "environment_targets",
        *(
            sa.column(name)
            for name in (
                "id",
                "provider_key",
                "identity_schema_version",
                "target_key",
                "target_identity_digest_sha256",
                "retention_behavior",
                "status",
                "active_run_count",
                "idle_at",
                "retire_after",
                "keeper_claim_generation",
                "keeper_owner_worker_generation",
                "keeper_lease_expires_at",
                "keeper_source_binding_id",
                "operation_generation",
                "operation_id",
                "requested_alive_until",
                "acknowledged_alive_until",
                "next_keepalive_at",
                "last_error",
                "created_at",
                "updated_at",
            )
        ),
    )
    for key, identity in identities.items():
        count = active_counts[key]
        connection.execute(
            targets.insert().values(
                **identity,
                status="active" if count else "idle",
                active_run_count=count,
                idle_at=None if count else now,
                retire_after=None if count else now + timedelta(hours=1),
                keeper_claim_generation=0,
                keeper_owner_worker_generation=None,
                keeper_lease_expires_at=None,
                keeper_source_binding_id=None,
                operation_generation=0,
                operation_id=None,
                requested_alive_until=None,
                acknowledged_alive_until=None,
                next_keepalive_at=None,
                last_error=None,
                updated_at=now,
            )
        )
    for revision_id, target_id in revision_targets.items():
        connection.execute(
            sa.text("UPDATE environment_revisions SET environment_target_id = :target_id WHERE id = :record_id"),
            {"target_id": target_id, "record_id": revision_id},
        )
    for binding_id, target_id in binding_targets.items():
        connection.execute(
            sa.text("UPDATE run_environment_bindings SET environment_target_id = :target_id WHERE id = :record_id"),
            {"target_id": target_id, "record_id": binding_id},
        )


